//! Player dress-up (Brief 36): the look (which piece of each slot + which colours) chosen in the
//! customization screen, the per-piece model spawn, and the colour application.
//!
//! Evidence: the catalogue is `data/player_parts_catalog.tsv`, generated by
//! `.tools/dressup_catalog.py` from the game's own `chara/table/dressup_table_p{1,2}.bin`
//! (VERIFIED: 134 pieces; p1 66, p2 68). The exporter (`player_export --catalog`) writes one
//! glTF per piece; the viewer spawns one scene per worn piece under `PlayerAvatar`.
//!
//! Colours:
//! - hair / eyebrow: 15 catalogue names (`appli/table/hair/hair_color_table.bin`), applied by
//!   swapping the base-colour texture for the baked variant PNG (RGB ASSUMED, see
//!   `assets::player_model::HAIR_COLOR_PALETTE`).
//! - eyes: 14 catalogue names (`p?_face0001_00_default_<name>` rows), iris-only tint baked per
//!   variant; `""` keeps the default blue-grey.
//! - skin: the four tones of `chara/table/skin_color_table.bin` (VERIFIED values), applied by
//!   multiplying the material base colour (`baseColorFactor` written by the exporter).
//! - clothes: the catalogue's colour/pattern suffixes are NOT applied: how the row index maps to
//!   the outfit texture is UNKNOWN (the material uses UV-index/layer masks that are not decoded).

use std::collections::BTreeMap;

use bevy::gltf::Gltf;
use bevy::prelude::*;

use super::art_style::ToonMaterial;
use bevy::world_serialization::WorldAssetRoot;

use super::player_anim::{PlayerMotion, PlayerSceneRef, PlayerSceneSpawned};
use super::PlayerAvatar;
use crate::assets::player_model::{EYE_COLOR_PALETTE, HAIR_COLOR_PALETTE};

/// The catalogue TSV, embedded so tests and the UI work without a cache.
pub const CATALOG_TSV: &str = include_str!("../../../../data/player_parts_catalog.tsv");

/// Skin tones of `chara/table/skin_color_table.bin` (VERIFIED sRGB values; the table has two
/// groups of the same four tones, one per protagonist variant).
pub const SKIN_TONES: [[u8; 3]; 4] = [[253, 232, 215], [252, 222, 220], [204, 162, 146], [139, 108, 103]];

/// Slot order used everywhere (spawn order, UI order).
pub const SLOTS: [&str; 10] = ["hrs", "face", "eyb", "eyew", "hdw", "drs", "tps", "btm", "ftw", "bag"];

// ---------------------------------------------------------------- look model

/// Which protagonist model family the look belongs to (Rei / Akari).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum LookVariant {
    #[default]
    P1,
    P2,
}

impl LookVariant {
    pub fn tag(self) -> &'static str {
        match self {
            Self::P1 => "p1",
            Self::P2 => "p2",
        }
    }
    pub fn parse(s: &str) -> Option<Self> {
        match s {
            "p1" => Some(Self::P1),
            "p2" => Some(Self::P2),
            _ => None,
        }
    }
    pub fn flip(self) -> Self {
        match self {
            Self::P1 => Self::P2,
            Self::P2 => Self::P1,
        }
    }
}

/// What the player wears on the body: a full set (dress) or a top + bottom pair.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Outfit {
    Set(String),
    TopBottom { top: String, bottom: String },
}

/// The full chosen look. Stems are catalogue ids (`p1_hrs0001_00_default`); the empty string
/// means "nothing in that slot" (hat, glasses).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PlayerLook {
    pub variant: LookVariant,
    pub hair: String,
    pub hair_color: String,
    pub eyebrow_color: String,
    /// Eye-contact colour name; `""` keeps the default blue-grey.
    pub eye_color: String,
    pub skin_tone: u8,
    pub outfit: Outfit,
    pub hat: String,
    pub glasses: String,
    pub shoes: String,
    pub bag: String,
}

impl Default for PlayerLook {
    fn default() -> Self {
        Self::default_for(LookVariant::P1)
    }
}

impl PlayerLook {
    /// The default look of a variant (the parts the merged exporter always used).
    pub fn default_for(variant: LookVariant) -> Self {
        let v = variant.tag();
        let hair = if v == "p1" { format!("{v}_hrs0001_00_default") } else { format!("{v}_hrs0002_00_default") };
        Self {
            variant,
            hair,
            hair_color: "darkbrown".into(),
            eyebrow_color: "darkbrown".into(),
            eye_color: String::new(),
            skin_tone: 0,
            outfit: Outfit::Set(format!("{v}_drs0001_00_default")),
            hat: String::new(),
            glasses: String::new(),
            shoes: format!("{v}_ftw0002_00_default"),
            bag: format!("{v}_bag0001_00_default"),
        }
    }

    /// `(slot, stem)` of every worn piece, in spawn order.
    pub fn pieces(&self) -> Vec<(&'static str, String)> {
        let v = self.variant.tag();
        let mut out: Vec<(&'static str, String)> = Vec::new();
        out.push(("hrs", self.hair.clone()));
        // The catalogue has exactly one face and one eyebrow piece per variant.
        out.push(("face", format!("{v}_face0001_00_default")));
        out.push(("eyb", format!("{v}_eyb0001_00_default")));
        if !self.glasses.is_empty() {
            out.push(("eyew", self.glasses.clone()));
        }
        if !self.hat.is_empty() {
            out.push(("hdw", self.hat.clone()));
        }
        match &self.outfit {
            Outfit::Set(stem) => out.push(("drs", stem.clone())),
            Outfit::TopBottom { top, bottom } => {
                out.push(("tps", top.clone()));
                out.push(("btm", bottom.clone()));
            }
        }
        out.push(("ftw", self.shoes.clone()));
        out.push(("bag", self.bag.clone()));
        out
    }

    /// Replace unknown stems with the defaults and clamp colours/tones. Returns notes for the
    /// caller to show (empty = the look was already valid). Pure, unit-tested.
    pub fn sanitize(&mut self, catalog: &LookCatalog) -> Vec<String> {
        let mut notes = Vec::new();
        let v = self.variant.tag().to_owned();
        let fix = |slot: &str, stem: &mut String, note: &mut Option<String>| {
            if !catalog.has(&v, slot, stem) {
                *note = Some(format!("{stem} is not a {slot} piece of {v}; using the default"));
                *stem = catalog.default_stem(&v, slot).unwrap_or_default();
            }
        };
        // Optional slots: an empty stem means "nothing worn" and stays valid; an unknown stem
        // is dropped rather than replaced (the player did not ask for that hat).
        let fix_optional = |slot: &str, stem: &mut String, note: &mut Option<String>| {
            if !stem.is_empty() && !catalog.has(&v, slot, stem) {
                *note = Some(format!("{stem} is not a {slot} piece of {v}; wearing none"));
                stem.clear();
            }
        };
        let mut n = None;
        fix("hrs", &mut self.hair, &mut n);
        if let Some(m) = n.take() {
            notes.push(m);
        }
        fix_optional("eyew", &mut self.glasses, &mut n);
        if let Some(m) = n.take() {
            notes.push(m);
        }
        fix_optional("hdw", &mut self.hat, &mut n);
        if let Some(m) = n.take() {
            notes.push(m);
        }
        match &mut self.outfit {
            Outfit::Set(stem) => fix("drs", stem, &mut n),
            Outfit::TopBottom { top, bottom } => {
                fix("tps", top, &mut n);
                if let Some(m) = n.take() {
                    notes.push(m);
                }
                fix("btm", bottom, &mut n);
            }
        }
        if let Some(m) = n.take() {
            notes.push(m);
        }
        fix("ftw", &mut self.shoes, &mut n);
        if let Some(m) = n.take() {
            notes.push(m);
        }
        fix("bag", &mut self.bag, &mut n);
        if let Some(m) = n.take() {
            notes.push(m);
        }
        if !HAIR_COLOR_PALETTE.iter().any(|(name, _)| *name == self.hair_color) {
            notes.push(format!("hair colour {} is not in the palette; using darkbrown", self.hair_color));
            self.hair_color = "darkbrown".into();
        }
        if !HAIR_COLOR_PALETTE.iter().any(|(name, _)| *name == self.eyebrow_color) {
            notes.push(format!("eyebrow colour {} is not in the palette; using darkbrown", self.eyebrow_color));
            self.eyebrow_color = "darkbrown".into();
        }
        if !self.eye_color.is_empty() && !EYE_COLOR_PALETTE.iter().any(|(name, _)| *name == self.eye_color) {
            notes.push(format!("eye colour {} is not in the palette; using the default", self.eye_color));
            self.eye_color.clear();
        }
        if self.skin_tone >= SKIN_TONES.len() as u8 {
            notes.push(format!("skin tone {} is out of range; using 0", self.skin_tone));
            self.skin_tone = 0;
        }
        notes
    }

    /// `key=value` lines of the save file's `look_` section (see `game::save_game`).
    pub fn save_lines(&self) -> Vec<String> {
        let outfit = match &self.outfit {
            Outfit::Set(stem) => format!("set:{stem}"),
            Outfit::TopBottom { top, bottom } => format!("top:{top}|bottom:{bottom}"),
        };
        vec![
            format!("look_variant={}", self.variant.tag()),
            format!("look_hair={}", self.hair),
            format!("look_hair_color={}", self.hair_color),
            format!("look_eyebrow_color={}", self.eyebrow_color),
            format!("look_eye_color={}", self.eye_color),
            format!("look_skin_tone={}", self.skin_tone),
            format!("look_outfit={outfit}"),
            format!("look_hat={}", self.hat),
            format!("look_glasses={}", self.glasses),
            format!("look_shoes={}", self.shoes),
            format!("look_bag={}", self.bag),
        ]
    }

    /// Read the `look_` keys of a save (missing keys = the default look, which is also the
    /// v9 -> v10 migration: the section simply did not exist before). Pure, unit-tested.
    pub fn from_save(keys: &BTreeMap<String, String>) -> Self {
        let variant = keys.get("look_variant").and_then(|v| LookVariant::parse(v)).unwrap_or_default();
        let mut look = Self::default_for(variant);
        if let Some(v) = keys.get("look_hair") {
            look.hair = v.clone();
        }
        if let Some(v) = keys.get("look_hair_color") {
            look.hair_color = v.clone();
        }
        if let Some(v) = keys.get("look_eyebrow_color") {
            look.eyebrow_color = v.clone();
        }
        if let Some(v) = keys.get("look_eye_color") {
            look.eye_color = v.clone();
        }
        if let Some(v) = keys.get("look_skin_tone").and_then(|t| t.parse::<u8>().ok()) {
            look.skin_tone = v;
        }
        if let Some(v) = keys.get("look_outfit") {
            if let Some(stem) = v.strip_prefix("set:") {
                look.outfit = Outfit::Set(stem.to_owned());
            } else if let Some(rest) = v.strip_prefix("top:") {
                let (top, bottom) = rest.split_once("|bottom:").unwrap_or((rest, ""));
                look.outfit = Outfit::TopBottom { top: top.to_owned(), bottom: bottom.to_owned() };
            }
        }
        if let Some(v) = keys.get("look_hat") {
            look.hat = v.clone();
        }
        if let Some(v) = keys.get("look_glasses") {
            look.glasses = v.clone();
        }
        if let Some(v) = keys.get("look_shoes") {
            look.shoes = v.clone();
        }
        if let Some(v) = keys.get("look_bag") {
            look.bag = v.clone();
        }
        look
    }
}

// ---------------------------------------------------------------- catalogue

/// One catalogue row (a piece of one variant and slot).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CatalogRow {
    pub variant: String,
    pub slot: String,
    pub stem: String,
}

/// The dress-up catalogue (parsed once from [`CATALOG_TSV`]).
#[derive(Debug, Clone, Default, Resource)]
pub struct LookCatalog {
    pub rows: Vec<CatalogRow>,
}

impl LookCatalog {
    pub fn builtin() -> Self {
        let mut rows = Vec::new();
        for line in CATALOG_TSV.lines() {
            if line.starts_with('#') || line.trim().is_empty() {
                continue;
            }
            let cols: Vec<&str> = line.split('\t').collect();
            if cols.len() < 3 || cols[0] == "variant:string*" {
                continue;
            }
            rows.push(CatalogRow { variant: cols[0].to_owned(), slot: cols[1].to_owned(), stem: cols[2].to_owned() });
        }
        Self { rows }
    }

    pub fn has(&self, variant: &str, slot: &str, stem: &str) -> bool {
        self.rows.iter().any(|r| r.variant == variant && r.slot == slot && r.stem == stem)
    }

    /// The first catalogue stem of a slot (the game lists the defaults first, so this is the
    /// variant's default piece; the exporter's default outfit matches it).
    pub fn default_stem(&self, variant: &str, slot: &str) -> Option<String> {
        self.rows.iter().find(|r| r.variant == variant && r.slot == slot).map(|r| r.stem.clone())
    }

    pub fn stems(&self, variant: &str, slot: &str) -> Vec<&str> {
        self.rows.iter().filter(|r| r.variant == variant && r.slot == slot).map(|r| r.stem.as_str()).collect()
    }
}

// ---------------------------------------------------------------- runtime

/// One worn piece to spawn.
#[derive(Clone)]
pub struct PieceRequest {
    pub slot: &'static str,
    pub gltf: Handle<Gltf>,
    /// Asset-relative directory of the piece (holds the glTF and the colour PNGs).
    pub dir: String,
    /// `(set, name, file)` colour variants of this piece (from its `colors.tsv`).
    pub colors: Vec<(String, String, String)>,
}

/// The worn pieces to render (child of `PlayerAvatar`). Spawned by the viewer from a
/// [`PlayerLook`]; replaces the single merged [`super::player_anim::PlayerModelSource`].
#[derive(Component, Clone)]
pub struct PlayerPieceSources {
    pub pieces: Vec<PieceRequest>,
}

/// Marks one spawned piece scene (its `PlayerSceneRef` carries the slot tag).
#[derive(Component, Clone, Copy, PartialEq, Eq)]
pub struct PieceScene {
    pub slot: &'static str,
}

/// The colours of a piece scene were applied.
#[derive(Component)]
pub struct PieceColored;

/// The live look (the customization screen writes it; the spawn/colour systems read it).
#[derive(Resource, Debug, Clone)]
pub struct PlayerLookState {
    pub look: PlayerLook,
}

impl Default for PlayerLookState {
    fn default() -> Self {
        Self { look: PlayerLook::default() }
    }
}

impl PlayerLookState {
    pub fn new(look: PlayerLook) -> Self {
        Self { look }
    }
}

/// Spawn one scene per worn piece under the avatar. Runs before the player-animation wiring.
fn spawn_piece_scenes(
    mut commands: Commands,
    gltfs: Res<Assets<Gltf>>,
    q: Query<(Entity, &PlayerPieceSources), (With<PlayerAvatar>, Without<PlayerSceneSpawned>)>,
) {
    for (e, src) in &q {
        let mut ready = true;
        let mut scenes = Vec::new();
        for piece in &src.pieces {
            let Some(gltf) = gltfs.get(&piece.gltf) else {
                ready = false;
                break;
            };
            let Some(scene) = gltf.default_scene.clone().or_else(|| gltf.scenes.first().cloned()) else {
                ready = false;
                break;
            };
            scenes.push((piece.clone(), scene));
        }
        if !ready || scenes.is_empty() {
            continue;
        }
        commands.entity(e).insert((PlayerSceneSpawned, PlayerMotion::default())).with_children(|p| {
            for (piece, scene) in scenes {
                p.spawn((
                    WorldAssetRoot(scene),
                    PlayerSceneRef { gltf: piece.gltf.clone(), slot: piece.slot.into() },
                    PieceScene { slot: piece.slot },
                    Transform::from_xyz(0.0, -super::player_anim::AVATAR_ROOT_ABOVE_GROUND, 0.0),
                    Visibility::default(),
                ));
            }
        });
    }
}

/// The colour variant file of a piece for `set` + `name`, if the exporter baked one.
fn color_file<'a>(piece: &'a PieceRequest, set: &str, name: &str) -> Option<&'a str> {
    piece.colors.iter().find(|(s, n, _)| s == set && n == name).map(|(_, _, f)| f.as_str())
}

fn skin_color(tone: u8) -> Color {
    let rgb = SKIN_TONES[tone as usize % SKIN_TONES.len()];
    Color::srgb_u8(rgb[0], rgb[1], rgb[2])
}

/// Swap the base-colour texture (and/or set the base colour) of a mesh's material. Handles both
/// the plain `StandardMaterial` and the toon copy made by `game::art_style` (which clones the
/// material once, so both must be kept in sync).
fn paint_material(
    std: Option<&MeshMaterial3d<StandardMaterial>>,
    toon: Option<&MeshMaterial3d<ToonMaterial>>,
    std_mats: &mut Assets<StandardMaterial>,
    toon_mats: &mut Assets<ToonMaterial>,
    texture: Option<Handle<Image>>,
    base: Option<Color>,
) {
    if let Some(handle) = std {
        if let Some(mut m) = std_mats.get_mut(&handle.0) {
            if let Some(t) = texture.clone() {
                m.base_color_texture = Some(t);
            }
            if let Some(c) = base {
                m.base_color = c;
            }
        }
    }
    if let Some(handle) = toon {
        if let Some(mut m) = toon_mats.get_mut(&handle.0) {
            if let Some(t) = texture {
                m.base.base_color_texture = Some(t);
            }
            if let Some(c) = base {
                m.base.base_color = c;
            }
        }
    }
}

/// Apply the chosen colours to every worn piece once its meshes exist: hair/eyebrow/eye texture
/// swaps by catalogue colour name, skin tone as a material base-colour multiply.
#[allow(clippy::type_complexity)]
fn apply_piece_colors(
    look: Res<PlayerLookState>,
    asset_server: Res<AssetServer>,
    sources: Query<&PlayerPieceSources>,
    pieces: Query<(Entity, &PieceScene, &PlayerSceneRef), Without<PieceColored>>,
    children: Query<&Children>,
    meshes: Query<(
        &Name,
        Option<&MeshMaterial3d<StandardMaterial>>,
        Option<&MeshMaterial3d<ToonMaterial>>,
    )>,
    mut std_mats: ResMut<Assets<StandardMaterial>>,
    mut toon_mats: ResMut<Assets<ToonMaterial>>,
    mut commands: Commands,
) {
    // The piece request of a spawned scene, matched by slot tag (one piece per slot).
    let request_of = |slot: &str| -> Option<&PieceRequest> {
        sources.iter().flat_map(|s| s.pieces.iter()).find(|p| p.slot == slot)
    };
    for (root, piece, _) in &pieces {
        let Some(request) = request_of(piece.slot) else {
            commands.entity(root).insert(PieceColored);
            continue;
        };
        let mut painted = 0usize;
        for d in children.iter_descendants(root) {
            let Ok((name, std, toon)) = meshes.get(d) else { continue };
            if std.is_none() && toon.is_none() {
                continue;
            }
            let mesh_name = name.as_str();
            let is_skin = mesh_name.contains("#face_skin") || mesh_name.contains("#body_skin") || mesh_name.contains("#face.");
            let mut texture: Option<Handle<Image>> = None;
            let mut base: Option<Color> = None;
            // Skin tone multiplies the skin-bound albedos of every piece.
            if is_skin {
                base = Some(skin_color(look.look.skin_tone));
            }
            match piece.slot {
                "hrs" => {
                    if let Some(file) = color_file(request, "hair", &look.look.hair_color) {
                        texture = Some(asset_server.load(format!("{}/{file}", request.dir)));
                    }
                }
                "eyb" => {
                    if let Some(file) = color_file(request, "eyebrow", &look.look.eyebrow_color) {
                        texture = Some(asset_server.load(format!("{}/{file}", request.dir)));
                    }
                }
                "face" => {
                    if !look.look.eye_color.is_empty() {
                        if mesh_name.contains("#eye") {
                            if let Some(file) = color_file(request, "eye", &look.look.eye_color) {
                                texture = Some(asset_server.load(format!("{}/{file}", request.dir)));
                            }
                        }
                    }
                }
                _ => {}
            }
            if texture.is_some() || base.is_some() {
                paint_material(std, toon, &mut std_mats, &mut toon_mats, texture, base);
                painted += 1;
            }
        }
        if painted > 0 {
            commands.entity(root).insert(PieceColored);
        }
    }
}

/// Rebuild the worn pieces when the look changes: despawn the piece scenes and re-request the
/// sources, so the spawn + wiring systems run again with the new pieces.
fn rebuild_look_pieces(
    mut commands: Commands,
    look: Res<PlayerLookState>,
    mut last: Local<Option<PlayerLook>>,
    avatars: Query<(Entity, &PlayerPieceSources), With<PlayerAvatar>>,
    pieces: Query<(Entity, &PieceScene)>,
) {
    if last.as_ref() == Some(&look.look) {
        return;
    }
    *last = Some(look.look.clone());
    for (e, sources) in &avatars {
        let _ = sources;
        for (piece_e, _) in &pieces {
            commands.entity(piece_e).despawn();
        }
        commands
            .entity(e)
            .remove::<PlayerSceneSpawned>()
            .remove::<super::player_anim::PlayerAnimState>()
            .remove::<PieceColored>();
    }
}

/// Registers the dress-up spawn/colour systems. The viewer inserts [`PlayerPieceSources`] and
/// [`PlayerLookState`]; without them (capsule avatar, or the merged fallback model) nothing runs.
pub struct DressupPlugin;

impl Plugin for DressupPlugin {
    fn build(&self, app: &mut App) {
        app.insert_resource(LookCatalog::builtin());
        app.init_resource::<PlayerLookState>();
        app.add_systems(
            Update,
            (
                rebuild_look_pieces,
                spawn_piece_scenes,
                apply_piece_colors.after(spawn_piece_scenes),
            )
                .chain()
                .before(super::player_anim::PlayerAnimSystems),
        );
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn catalog() -> LookCatalog {
        LookCatalog::builtin()
    }

    #[test]
    fn the_catalogue_has_every_piece_of_both_variants() {
        let c = catalog();
        assert_eq!(c.rows.len(), 134, "66 p1 + 68 p2 pieces");
        for (variant, count) in [("p1", 66), ("p2", 68)] {
            assert_eq!(c.rows.iter().filter(|r| r.variant == variant).count(), count, "{variant}");
        }
        for slot in SLOTS {
            assert!(c.rows.iter().any(|r| r.slot == slot), "slot {slot} is missing");
        }
        // Every stem is unique per variant and starts with the variant tag.
        let mut stems: Vec<&str> = c.rows.iter().map(|r| r.stem.as_str()).collect();
        stems.sort_unstable();
        stems.dedup();
        assert_eq!(stems.len(), c.rows.len());
        assert!(c.rows.iter().all(|r| r.stem.starts_with(&r.variant)));
    }

    #[test]
    fn default_looks_are_in_the_catalogue() {
        for variant in [LookVariant::P1, LookVariant::P2] {
            let mut look = PlayerLook::default_for(variant);
            let notes = look.sanitize(&catalog());
            assert!(notes.is_empty(), "{variant:?}: {notes:?}");
            for (slot, stem) in look.pieces() {
                assert!(catalog().has(variant.tag(), slot, &stem), "{slot} {stem}");
            }
        }
    }

    #[test]
    fn save_lines_round_trip() {
        for variant in [LookVariant::P1, LookVariant::P2] {
            let mut look = PlayerLook::default_for(variant);
            look.hair_color = "blond".into();
            look.eye_color = "green".into();
            look.skin_tone = 3;
            look.hat = catalog().default_stem(variant.tag(), "hdw").unwrap();
            look.outfit = Outfit::TopBottom {
                top: catalog().default_stem(variant.tag(), "tps").unwrap(),
                bottom: catalog().default_stem(variant.tag(), "btm").unwrap(),
            };
            let keys: BTreeMap<String, String> = look
                .save_lines()
                .into_iter()
                .filter_map(|l| l.split_once('=').map(|(k, v)| (k.to_owned(), v.to_owned())))
                .collect();
            assert_eq!(PlayerLook::from_save(&keys), look);
        }
    }

    #[test]
    fn a_v9_save_without_the_section_loads_the_default_look() {
        let keys = BTreeMap::new();
        let look = PlayerLook::from_save(&keys);
        assert_eq!(look, PlayerLook::default_for(LookVariant::P1));
    }

    #[test]
    fn sanitize_replaces_unknown_pieces_and_colours() {
        let mut look = PlayerLook::default_for(LookVariant::P1);
        look.hair = "p1_hrs9999_00_unicorn".into();
        look.hat = "p2_hdw0001_00_hunting".into();
        look.shoes = "p1_ftw9999_00_none".into();
        look.hair_color = "rainbow".into();
        look.eye_color = "x-ray".into();
        look.skin_tone = 9;
        look.outfit = Outfit::Set("p1_drs9999_00_none".into());
        let notes = look.sanitize(&catalog());
        assert_eq!(notes.len(), 7, "{notes:?}");
        assert_eq!(look.hair, "p1_hrs0001_00_default");
        assert!(look.hat.is_empty(), "an unknown hat is dropped, not replaced");
        assert_eq!(look.shoes, "p1_ftw0001_00_sandals");
        assert_eq!(look.hair_color, "darkbrown");
        assert!(look.eye_color.is_empty());
        assert_eq!(look.skin_tone, 0);
        assert_eq!(look.outfit, Outfit::Set("p1_drs0001_00_default".into()));
        // A sanitized look passes a second round untouched.
        assert!(look.sanitize(&catalog()).is_empty());
    }

    #[test]
    fn an_empty_hat_and_glasses_are_valid_and_spawn_nothing() {
        let look = PlayerLook::default_for(LookVariant::P1);
        let pieces = look.pieces();
        assert!(!pieces.iter().any(|(slot, _)| *slot == "hdw" || *slot == "eyew"));
        assert_eq!(pieces.len(), 6, "hair, face, eyebrows, dress, shoes, bag (no hat/glasses)");
    }

    #[test]
    fn the_skin_tone_colours_are_the_decoded_table_rows() {
        // VERIFIED values of chara/table/skin_color_table.bin.
        assert_eq!(SKIN_TONES[0], [253, 232, 215]);
        assert_eq!(SKIN_TONES[3], [139, 108, 103]);
        let c = skin_color(2);
        let s = c.to_srgba();
        assert_eq!((s.red * 255.0).round() as u8, 204);
        assert_eq!((s.green * 255.0).round() as u8, 162);
        assert_eq!((s.blue * 255.0).round() as u8, 146);
    }
}
